std::optional<std::string> Field(const std::string& json,const std::string& key){auto p=json.find("\""+key+"\"");if(p==std::string::npos)return{};p=json.find(':',p);if(p==std::string::npos)return{};++p;while(p<json.size()&&isspace(static_cast<unsigned char>(json[p])))++p;if(p>=json.size())return{};if(json[p]=='"'){auto e=json.find('"',p+1);if(e==std::string::npos)return{};return json.substr(p+1,e-p-1);}auto e=p;while(e<json.size()&&json[e]!=','&&json[e]!='}'&&!isspace(static_cast<unsigned char>(json[e])))++e;return json.substr(p,e-p);}
bool U64(const std::string& value,uint64_t& out){try{size_t used=0;out=std::stoull(value,&used,0);return used==value.size();}catch(...){return false;}}
bool Boolean(const std::string& value,bool& out){if(value=="true"){out=true;return true;}if(value=="false"){out=false;return true;}return false;}
bool Bytes(const std::string& text,std::vector<uint8_t>& out){out.clear();std::istringstream in(text);std::string token;while(in>>token){if(token.size()!=2)return false;try{size_t used=0;auto value=std::stoul(token,&used,16);if(used!=2||value>255)return false;out.push_back(uint8_t(value));}catch(...){return false;}}return !out.empty();}
bool Register(const std::string& text,X64RegisterId& out){for(unsigned i=0;i<16;++i)if(text==X64RegisterName(X64RegisterId(i))){out=X64RegisterId(i);return true;}out=X64RegisterId::Invalid;return false;}
bool IsExecutable(const TargetInfo& target,uint64_t rva){for(auto range:target.image.executableRanges)if(rva>=range.rva&&rva-range.rva<range.size)return true;return false;}
const char* RequiredV1[]={"initialPrepRva","initialCallRva","initialReturnRva","sharedWorkerRva","producerRva","templateLookupRva","wrapperRva","initialHandlerRva","dispatchRva","linkedActivationRva","periodicUpdateRva"};
const char* RequiredV2[]={"initialPrepRva","initialCallRva","initialReturnRva","sharedWorkerRva","producerRva","producerCallRva","typedActorLookupRva","targetBuilderRva","targetBuilderVectorRva","differentialParsedRva","idSerializationRva","typeSerializationRva","templateLookupRva","wrapperRva","initialHandlerRva","dispatchRva","linkedActivationRva","periodicUpdateRva","monsterCategoryWriteRva","charCategoryWriteRva","npcCategoryWriteRva","recallCategoryWriteRva"};
const char* RequiredV3[]={"initialPrepRva","initialCallRva","initialReturnRva","sharedWorkerRva","producerRva","producerCallRva","typedActorLookupRva","targetBuilderRva","targetBuilderVectorRva","differentialParsedRva","idSerializationRva","typeSerializationRva","templateLookupRva","locator_AoeLifecycleCaller","locator_AoeFunctionRecordDispatch","locator_SharedOperation020A","locator_TypedActorLookup","locator_SharedTypedActorCall","locator_OperationProducer","locator_ProducerCall","locator_RecordSerialization","locator_TemplateLookup","locator_LinkedAcquisitionPath","locator_AcquisitionType2Insertion","locator_AcquisitionRadiusGuard","locator_TargetVectorBuilder","locator_ParsedActionBoundary"};
bool NumberField(const std::string& json,const char* name,uint64_t& value,std::string& error){auto field=Field(json,name);if(!field||!U64(*field,value)){error=std::string("Missing or invalid profile field: ")+name;return false;}return true;}
bool ByteField(const std::string& json,const char* name,std::vector<uint8_t>& value,std::string& error){auto field=Field(json,name);if(!field||!Bytes(*field,value)){error=std::string("Missing or invalid fingerprint: ")+name;return false;}return true;}
void LegacyRuntime(BuildProfile& p,const std::string& json){auto a=[&](const char* n){auto* x=FindProfileAnchor(p,n);return x?x->rva:0;};auto& r=p.runtime;r.initialPrepRva=a("initialPrepRva");r.initialCallRva=a("initialCallRva");r.initialReturnRva=a("initialReturnRva");r.sharedWorkerRva=a("sharedWorkerRva");r.producerRva=a("producerRva");r.producerCallRva=0x7BB4B7;r.typedActorLookupRva=0x7B9BD0;r.targetBuilderVectorRva=0x6CC60;r.differentialParsedRva=0x6CC93;r.idSerializationRva=0x993DC;r.typeSerializationRva=0x993E6;r.targetVectorOffset=0x660;r.actorIdOffset=0x768;r.actorTypeOffset=0x7E1;r.actorEligibilityOffset=0x7CA;r.actorStatusOffset=0x7E4;r.localActorOffset=0x2710;r.actorPositionOffset=0xB0;r.actorTreeOffsets[1]=0x1140;r.actorTreeOffsets[2]=0x1120;r.actorTreeOffsets[7]=0x11B0;r.actorTreeOffsets[9]=0x1130;r.actorTreeOffsets[10]=0xC6FF00;r.actorTreeOffsets[11]=0x11A0;r.actorTreeOffsets[17]=0x1150;r.actorTreeOffsets[19]=0x11E0;r.targetRecordBytes=8;r.targetMaximumEntries=32;r.targetInspectorAvailable=true;r.initialNxAvailable=true;r.liveValidationRequired=false;if(auto f=Field(json,"initialPrepExpectedBytes"))Bytes(*f,r.initialPrepBytes);if(auto f=Field(json,"initialCallExpectedBytes"))Bytes(*f,r.initialCallBytes);if(auto f=Field(json,"initialReturnExpectedBytes"))Bytes(*f,r.initialReturnBytes);Bytes("41 54 41 55 41 56 41 57 48 81 EC 58 01 00 00",r.sharedWorkerBytes);Bytes("48 89 5C 24 08 48 89 6C 24 10 48 89 74 24 18 57",r.producerBytes);Bytes("E8 84 DD 8D FF",r.producerCallBytes);Bytes("85 D2 74 4A 41 0F B6 C0 FF C8 83 F8 12 77 3F",r.typedActorLookupBytes);Bytes("48 8D 8F 60 06 00 00",r.targetBuilderVectorBytes);Bytes("66 47 39 74 6F 3C",r.differentialParsedBytes);Bytes("48 8D 4C 24 28 E8 9A 66 95 00",r.idSerializationBytes);Bytes("48 8B C8 0F B6 D3 E8 0F 65 95 00",r.typeSerializationBytes);}
